import {colorFields,validColor} from './model.mjs';
const $=id=>document.getElementById(id),frame=$('preview'),controls=new Map();let selection=null,colors=new Map(),generation=0;
function origin(){try{return new URL(frame.src).origin;}catch{return null;}}
const send=data=>{if(origin())frame.contentWindow.postMessage(data,origin());};
function merge(items){for(const c of items||[]){if(typeof c.name==='string'&&/^--[\w-]+$/.test(c.name)&&validColor(c.value))colors.set(c.name,c.value);}for(const {tokens} of controls.values()){tokens.replaceChildren(new Option('서비스 색상에서 선택',''));for(const [name,value] of colors){const fallback=/^#[\da-f]+$/i.test(value)?`, ${value}`:'';tokens.add(new Option(`${name.replace(/^--color-?/,'')} · ${value}`,`var(${name}${fallback})`));}}$('palette-status').textContent=colors.size?`서비스 색상 ${colors.size}개 · 직접 색상 입력도 가능합니다.`:'정의된 색상을 찾지 못했어요. 아래에서 직접 색상을 선택할 수 있습니다.';}
for(const property of colorFields.filter(p=>!['fill','stroke'].includes(p))){const title={color:'글자색',backgroundColor:'배경색',borderColor:'테두리색'}[property],row=document.createElement('div');row.className='color-row';row.innerHTML=`<label>${title}<input type="color" aria-label="${title} 선택"></label><input type="text" aria-label="${title} 색상값" placeholder="#12a8bf"><select aria-label="${title} 서비스 색상"></select>`;const picker=row.querySelector('[type=color]'),input=row.querySelector('[type=text]'),tokens=row.querySelector('select');const apply=value=>{input.value=value;if(!validColor(value)){input.setCustomValidity('HEX, RGB 또는 서비스 색상을 입력하세요.');return;}input.setCustomValidity('');send({type:'dragger:style',selection,property,value,unit:''});};picker.oninput=()=>{tokens.value='';apply(picker.value);};input.onchange=()=>{tokens.value='';apply(input.value.trim());};tokens.onchange=()=>{if(tokens.value)apply(tokens.value);};controls.set(property,{picker,input,tokens});$('color-controls').append(row);}
function sync(values){for(const [property,{input,picker,tokens}] of controls){const value=String(values?.[property]||'');input.value=value;input.setCustomValidity('');tokens.value=value;const rgb=value.match(/^rgba?\(\s*(\d+)[, ]+\s*(\d+)[, ]+\s*(\d+)/i);if(/^#[\da-f]{6}$/i.test(value))picker.value=value;else if(rgb)picker.value='#'+rgb.slice(1,4).map(x=>Math.min(255,Number(x)).toString(16).padStart(2,'0')).join('');}}
new MutationObserver(()=>{$('colors').disabled=true;selection=null;}).observe(frame,{attributes:true,attributeFilter:['src']});
addEventListener('message',async e=>{if(e.source!==frame.contentWindow||e.origin!==origin())return;const m=e.data;
 if(m?.type==='dragger:ready'){$('colors').disabled=true;selection=null;const version=++generation;colors.clear();merge([]);send({type:'dragger:palette'});try{const r=await fetch('/api/source/palette',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({appOrigin:origin()})});const data=await r.json();if(r.ok&&version===generation)merge(data.colors);}catch{}}
 if(m?.type==='dragger:selection'){selection=m.selection;$('colors').disabled=!selection;sync(m.values);send({type:'dragger:palette'});}
 if(m?.type==='dragger:palette')merge(m.colors);
});
